import{_ as a,o as r,c as t,a2 as n}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"安装电脑端","description":"","frontmatter":{},"headers":[],"relativePath":"agents-anywhere/connectors.md","filePath":"agents-anywhere/connectors.md","lastUpdated":1786867856000}'),o={name:"agents-anywhere/connectors.md"};function l(i,e,s,h,c,d){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="安装电脑端" tabindex="-1">安装电脑端 <a class="header-anchor" href="#安装电脑端" aria-label="Permalink to &quot;安装电脑端&quot;">​</a></h1><p>在哪台电脑上运行 Codex，就在哪台电脑上安装。下载页面中的 <strong>Connector</strong>，就是这里说的“电脑端”。</p><h2 id="安装前" tabindex="-1">安装前 <a class="header-anchor" href="#安装前" aria-label="Permalink to &quot;安装前&quot;">​</a></h2><p>先在电脑上打开 Codex，确认它可以正常使用；然后登录<a href="https://agents.liangkezaoshu.top/zh-CN" target="_blank" rel="noreferrer">手机远程控制台</a>。</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><ol><li>从<a href="https://github.com/anywhere-labs/Agents-Anywhere/releases" target="_blank" rel="noreferrer">官方下载页</a>下载 Windows 安装包。</li><li>安装并打开电脑端。</li><li>在控制台选择 <strong>设备 → 添加设备</strong>，按提示完成绑定。</li><li>看到电脑显示“在线”即可。</li></ol><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><ol><li>从<a href="https://github.com/anywhere-labs/Agents-Anywhere/releases" target="_blank" rel="noreferrer">官方下载页</a>选择 Apple Silicon 或 Intel 安装包。</li><li>安装并打开，允许系统要求的网络和文件权限。</li><li>在控制台选择 <strong>设备 → 添加设备</strong>，按提示完成绑定。</li><li>看到电脑显示“在线”即可。</li></ol><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><ol><li>在控制台选择 <strong>设备 → 添加设备 → Linux</strong>。</li><li>复制页面生成的命令，在电脑终端运行。</li><li>保持这个进程运行，看到电脑显示“在线”即可。</li></ol><div class="warning custom-block"><p class="custom-block-title">不要分享绑定命令</p><p>绑定命令里包含设备凭据，只能在自己的电脑上运行。</p></div><p>接下来：<a href="/agents-anywhere/android">在手机上新建第一个任务</a>。</p>',12)])])}const _=a(o,[["render",l]]);export{u as __pageData,_ as default};
